-- MIMT: Web Push notifications for app.mimt.ca (new text, voicemail…). API: apps/api/src/routes/push.ts.
-- The server's VAPID key pair is generated by the API on first use and stored ENCRYPTED (MessageCipher) in
-- server_keys, so no key has to be pasted anywhere. RLS on everywhere, API only.

create table web_push_subscriptions (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references users(id) on delete cascade,
  endpoint      text not null unique check (endpoint ~ '^https://' and char_length(endpoint) <= 2048),
  p256dh        text not null check (char_length(p256dh) between 16 and 256),
  auth          text not null check (char_length(auth) between 8 and 128),
  created_at    timestamptz not null default now()
);
create index web_push_subscriptions_user_idx on web_push_subscriptions(user_id);

create table server_keys (
  name             text primary key check (name ~ '^[a-z0-9_]{1,40}$'),
  value_encrypted  text not null,
  created_at       timestamptz not null default now()
);

alter table web_push_subscriptions enable row level security;
alter table server_keys enable row level security;
